import {$,intro} from './ui.js';
const solderSteps=[
 ['Prepare the work','Disconnect all power and discharge stored energy. Secure the practice PCB in a holder. Use eye protection, a stable iron stand, and local fume extraction. Wash hands after handling solder; keep food away from the bench.'],
 ['Fit & check the component','Start with a through-hole resistor. Insert it fully enough for the intended mounting and bend the leads gently to hold it. For polarized parts, check the exact datasheet and the board orientation before heating.'],
 ['Clean, tin & make contact','Use a suitable chisel tip. Clean it with brass wool or an appropriate damp sponge, then add a thin layer of solder. Choose temperature for your solder alloy and task. Place the tip against both the pad and lead to transfer heat.'],
 ['Feed solder into the joint','Touch electronics solder to the heated pad and lead, on the side opposite the tip. Add only enough for a concave fillet that wets both surfaces. Use electronics flux as needed; plumbing flux is unsuitable for a PCB.'],
 ['Remove solder, then the iron','Stop feeding solder first, then lift the iron away. If wetting is slow, stop and let the board cool. Revisit cleanliness, flux, and tip contact rather than heating indefinitely. Excess heat can lift a pad.'],
 ['Keep it still while it cools','Let the joint solidify without movement. Do not blow on it. After cooling, trim the excess lead with flush cutters and contain the clipped end. Clean flux residue when the flux or assembly instructions require it.'],
 ['Inspect & test','Look for wetting to both pad and lead, a smooth fillet, and no bridges. Lead-free solder can be matte and still be good. With power disconnected, check intended continuity and inspect for shorts before powering up.']
];let step=0;
function joint(kind='good',stage=6){const good=kind==='good',cold=kind==='cold',bridge=kind==='bridge';return `<svg class="joint-art" viewBox="0 0 400 230" role="img" aria-label="${stage<6?'Soldering step illustration':'Illustrated solder joint for inspection'}"><defs><linearGradient id="metal-${kind}-${stage}" x1="0" x2="1"><stop stop-color="#8fa5a0"/><stop offset=".48" stop-color="#e4eae4"/><stop offset="1" stop-color="#8fa5a0"/></linearGradient></defs><rect x="40" y="153" width="320" height="32" rx="3" fill="#44755c"/><rect x="146" y="148" width="98" height="9" rx="2" fill="#c1a069"/><rect x="185" y="65" width="15" height="130" fill="#b3bfb4"/><path d="M186 65q0-30 15-30h23" stroke="#b3bfb4" stroke-width="8" fill="none"/>${stage>=3?bridge?'<rect x="283" y="148" width="50" height="9" fill="#c1a069"/><rect x="302" y="87" width="12" height="107" fill="#aebfb3"/><path d="M160 148Q178 128 185 117H200Q217 130 230 132L285 132Q298 130 301 122H313L330 150Z" fill="#b6c5bb"/>':cold?`<path d="M162 145C140 123 169 99 185 118C219 103 234 140 205 147Z" fill="url(#metal-${kind}-${stage})"/><path d="M161 150h61" stroke="#385b44" stroke-width="4"/>`:`<path d="M155 148Q181 141 185 112H200Q204 140 236 148Z" fill="url(#metal-${kind}-${stage})"/>`:''}${stage===2||stage===3||stage===4?'<g transform="rotate(-37 283 80)"><rect x="260" y="-35" width="36" height="94" rx="8" fill="#355448"/><path d="M269 59h18v78l-9 24-9-24Z" fill="#a1b0a5"/></g>':''}${stage===3?'<path d="M38 90Q90 74 150 130" stroke="#bbc4b7" stroke-width="5" fill="none"/><text x="35" y="57">Solder wire</text>':''}<text x="53" y="209">PCB</text><text x="265" y="177" fill="#dce7c9">Copper pad</text>${stage>=5?'<text x="63" y="58">Inspect both surfaces</text>':''}</svg>`}
export function solder(){
 $('#main').innerHTML=intro('03 / make a connection that lasts','A steady hand.<br><em>A sound connection.</em>','Learn the sequence, then train your eye. Start with a practice board and inexpensive through-hole parts.')+`<div class="safety-strip"><strong>Your first bench rule</strong><p>Practise on disconnected, low-voltage hobby circuits. Leave mains-powered equipment, power supplies, and lithium battery packs for supervised training. Hot tips, fumes, and stored charge deserve care.</p></div><section class="practice-grid"><div class="white-panel"><div class="panel-top"><span class="section-label">Your first through-hole joint</span><span class="pill" id="step-count"></span></div><div class="step-list" aria-label="Soldering steps">${solderSteps.map((_,i)=>`<button data-step="${i}" aria-label="Step ${i+1}: ${solderSteps[i][0]}">${i+1}</button>`).join('')}</div><div id="solder-step"></div><div class="step-actions"><button class="btn outline small" id="previous-step">← Previous</button><button class="btn small" id="next-step">Next step →</button></div></div><aside class="white-panel"><div class="eyebrow">A few things that matter</div><h3>Heat the connection,<br>then add the solder.</h3><ol><li><strong>Tip contact beats extra temperature.</strong> A chisel tip with enough contact area transfers heat better than a tiny point.</li><li><strong>Flux helps metal wet.</strong> It removes oxides during soldering. A dirty or oxidized surface makes solder bead up.</li><li><strong>The right amount is a small amount.</strong> Aim for a fillet that joins pad and lead, not a ball hiding the connection.</li><li><strong>Time is not universal.</strong> Pad size, ground planes, tip, solder, and station recovery change the heating time.</li><li><strong>Practise rework too.</strong> Add suitable flux and use solder wick or a pump. Never pull a lead through solid solder.</li></ol><p class="small-note">These diagrams teach the sequence. Physical practice, magnification, and electrical checks are still needed.</p><a class="resource" href="https://learn.sparkfun.com/tutorials/how-to-solder-through-hole-soldering" target="_blank" rel="noreferrer">Watch a real soldering demonstration <span>↗</span><small>SparkFun · through-hole soldering</small></a></aside></section><div class="section-heading"><h2>Train your eye.</h2><p>Inspect each illustration and choose the best description.</p></div><section class="defect-grid">${['good','cold','bridge'].map((k,i)=>`<article class="defect">${joint(k)}<span class="section-label">Joint ${String(i+1).padStart(2,'0')}</span><label class="small-note" for="joint-${i}">What do you see?</label><select id="joint-${i}" data-joint="${k}"><option value="">Choose a diagnosis</option><option value="bridge">Solder bridge</option><option value="good">Well-wetted fillet</option><option value="cold">Poor wetting / balled solder</option></select><p class="feedback" id="joint-feedback-${i}" role="status"></p></article>`).join('')}</section><div class="unit-tools"><section class="white-panel"><div class="eyebrow">Next soldering challenge</div><h3>From through-hole to SMD</h3><p class="small-note">Try 1206 or 0805 passive parts on a practice board. Tin one pad, position the part with tweezers, reflow to tack it, then solder the other end. Check alignment and reflow the first end if needed. Fine-pitch ICs and hot-air rework can come later.</p></section><section class="white-panel"><div class="eyebrow">A repair habit worth building</div><h3>Inspect → measure → change</h3><p class="small-note">Take a photo before removing parts. Record orientation and values. Repair a known fault, then measure again. A shiny joint alone is not evidence that the whole circuit works.</p><a class="btn outline small" style="margin-top:15px" href="#meter">Practise measuring →</a></section></div>`;
 renderStep();$('#main').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.step!==undefined)step=+b.dataset.step;if(b.id==='next-step')step=Math.min(6,step+1);if(b.id==='previous-step')step=Math.max(0,step-1);renderStep()};$('#main').onchange=e=>{if(!e.target.dataset.joint)return;const expected=e.target.dataset.joint,ok=e.target.value===expected;const advice={good:'A concave fillet wets the pad and lead. This is the target shape; still inspect all sides and test the circuit.',cold:'The solder beads up and does not wet the pad. Clean, add appropriate flux, and reheat both pad and lead. Dull appearance alone is not proof of a bad joint.',bridge:'Solder joins two adjacent pads. Disconnect power, use flux and wick to remove the excess, then inspect and verify the pads are not unintentionally connected.'};e.target.nextElementSibling.textContent=e.target.value?(ok?'Correct. ':'Look again. ')+advice[expected]:''};
}
function renderStep(){$('#step-count').textContent=`${step+1} / 7`;document.querySelectorAll('[data-step]').forEach(b=>{b.classList.toggle('active',+b.dataset.step===step);b.setAttribute('aria-current',+b.dataset.step===step?'step':'false')});$('#solder-step').innerHTML=joint('good',step)+`<div class="step-copy"><h3>${solderSteps[step][0]}</h3><p style="margin-top:12px">${solderSteps[step][1]}</p></div>`;$('#previous-step').disabled=step===0;$('#next-step').disabled=step===6;$('#next-step').textContent=step===6?'Sequence complete':'Next step →'}
let meterState={mode:'voltage',power:true,fault:'healthy',red:'B',black:'C',jack:'voltage',series:false,probe:'red'};
export function meter(){const s=meterState;$('#main').innerHTML=intro('04 / measure. don’t guess.','A good question.<br><em>A useful reading.</em>','Place probes, choose a mode, and introduce a fault. Learn what a measurement can—and cannot—tell you.')+`<section class="meter-grid"><div><div class="meter-board"><div class="panel-top"><span class="section-label">The practice circuit</span><span class="pill">5 V · two 1 kΩ resistors</span></div><svg viewBox="0 0 560 350" role="group" aria-label="Circuit measurement nodes A, B, and C"><path d="M110 130V60H365V280H110V195" class="wire"/><path d="M90 146h40m-30 16h20M110 130v16m0 16v33" class="symbol"/><path d="M365 75v8l-10 5 20 10-20 10 20 10-20 10 10 5v12M365 203v8l-10 5 20 10-20 10 20 10-20 10 10 5v12" class="symbol"/><text x="59" y="165">5 V</text><text x="400" y="115">R1 · 1 kΩ</text><text x="400" y="240">R2 · 1 kΩ</text>${[['A',365,60],['B',365,174],['C',365,280]].map(([n,x,y])=>`<g role="button" tabindex="0" data-node="${n}" aria-label="Place selected probe at node ${n}"><circle class="node" cx="${x}" cy="${y}" r="13"/><text x="${x+29}" y="${y+5}">${n}${n==='C'?' · ground':''}</text></g>`).join('')}<g id="fault-art"></g><g id="probe-marks"></g><text x="55" y="326" id="fault-caption"></text></svg><div class="probe-target" aria-label="Active probe"><button data-probe="red">Place red probe</button><button data-probe="black">Place black probe</button></div><p class="small-note">Select a probe, then click a labeled node. Keyboard and dropdown controls work too. The black lead stays in COM.</p></div><p class="meter-feedback" id="meter-feedback" role="status"></p><section class="challenge" style="margin-top:25px"><div class="eyebrow">Try these measurements</div><h3>Start healthy: measure A → C, then B → C.</h3><p class="small-note">Expect 5 V, then 2.5 V. Swap red and black: the sign reverses. Now introduce an open R1: B falls to ground, so B → C reads 0 V. A zero reading is a clue, not a complete diagnosis.</p></section></div><div class="meter-controls"><div class="meter-body"><div class="meter-screen" id="meter-screen" aria-live="polite"></div><div class="meter-knob"></div><div class="meter-jacks"><span>COM · BLACK</span><span id="jack-label">V / Ω · RED</span></div></div><div class="control"><label for="meter-mode">Meter mode</label><select id="meter-mode"><option value="voltage">DC voltage · across two points</option><option value="resistance">Resistance · unpowered circuit</option><option value="continuity">Continuity · unpowered circuit</option><option value="current">DC current · in series</option></select></div><div class="probe-selectors">${['red','black'].map(p=>`<div class="control"><label for="probe-${p}">${p==='red'?'Red':'Black'} probe</label><select id="probe-${p}">${['A','B','C'].map(n=>`<option ${s[p]===n?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}</div><div class="control"><label for="meter-jack">Red lead jack</label><select id="meter-jack"><option value="voltage">V / Ω jack</option><option value="current">Fused mA jack</option></select></div><label class="toggle-control"><input id="meter-power" type="checkbox" ${s.power?'checked':''}>Connect the 5 V supply</label><label class="toggle-control"><input id="meter-series" type="checkbox" ${s.series?'checked':''}>Insert meter in series with the supply</label><div class="control"><label for="meter-fault">Introduce a fault</label><select id="meter-fault"><option value="healthy">Healthy circuit</option><option value="open">Open top resistor R1</option><option value="short">Short across bottom resistor R2</option></select></div><p class="small-note">Power off disconnects the source completely in this model. Never use resistance or continuity on a powered circuit. In current mode, across-node probing is blocked: it can short a circuit and blow the meter fuse.</p></div></section><p class="source-note">Further reading: <a href="https://learn.adafruit.com/multimeters/overview?view=all" target="_blank" rel="noreferrer">Adafruit’s multimeter guide ↗</a> These are ideal measurements; real meters have input impedance, burden voltage, limits, and fuses.</p>`;
 $('#meter-mode').value=s.mode;$('#meter-fault').value=s.fault;$('#meter-jack').value=s.jack;
 $('#main').onchange=e=>{const map={'meter-mode':'mode','meter-power':'power','meter-fault':'fault','probe-red':'red','probe-black':'black','meter-jack':'jack','meter-series':'series'},key=map[e.target.id];if(key){s[key]=e.target.type==='checkbox'?e.target.checked:e.target.value;updateMeter()}};
 $('#main').onclick=e=>{const probe=e.target.closest('[data-probe]'),node=e.target.closest('[data-node]');if(probe){s.probe=probe.dataset.probe;updateMeter()}if(node){s[s.probe]=node.dataset.node;$('#probe-'+s.probe).value=node.dataset.node;updateMeter()}};
 $('#main').onkeydown=e=>{const node=e.target.closest('[data-node]');if(node&&['Enter',' '].includes(e.key)){e.preventDefault();node.dispatchEvent(new MouseEvent('click',{bubbles:true}))}};updateMeter();
}
function updateMeter(){const s=meterState;let reading='',unit='',message='';const v={A:s.power?5:0,B:s.power&&s.fault==='healthy'?2.5:0,C:0},indices={A:0,B:1,C:2};let r=0;const start=Math.min(indices[s.red],indices[s.black]),end=Math.max(indices[s.red],indices[s.black]);for(let i=start;i<end;i++)r+=i===0?(s.fault==='open'?Infinity:1000):(s.fault==='short'?0:1000);
 if(s.mode==='current'){if(s.jack!=='current'){reading='CHECK';message='Move the red lead to the appropriate fused current jack and select a suitable range. For this model, choose the fused mA jack.'}else if(!s.series){reading='STOP';message='Current mode has a low-resistance path through the meter. Across two circuit nodes it can create a short. Disconnect power, break the circuit, then insert the meter in series.'}else{reading=(!s.power||s.fault==='open'?0:s.fault==='short'?5:2.5).toFixed(2);unit='mA';message='The meter is inserted in the supply path. All loop current flows through it. Return the red lead to V / Ω after a current measurement.'}}
 else if(s.jack==='current'){reading='CHECK';message='Return the red lead to the V / Ω jack before this measurement. Leaving it in a current jack can short the circuit.'}
 else if(s.series){reading='CHECK';message='Remove the series insertion and use the selected node pair for voltage, resistance, or continuity.'}
 else if(s.mode==='voltage'){reading=(v[s.red]-v[s.black]).toFixed(2);unit='V DC';message=s.power?`The reading is V(${s.red}) − V(${s.black}). ${s.red===s.black?'Both probes touch the same node, so the difference is zero.':s.fault==='open'?'R1 is open, so no current reaches the midpoint; R2 ties B to ground.':s.fault==='short'?'R2 is bypassed, so B is tied directly to ground. R1 still limits current.':'The equal resistors split the 5 V supply equally.'}`:'The source is disconnected in this ideal circuit, so every node has 0 V difference. On real boards, verify stored charge separately.'}
 else if(s.power){reading='STOP';message='Disconnect power before resistance or continuity measurements. An energized circuit gives invalid readings and can damage the meter.'}
 else if(s.mode==='resistance'){reading=Number.isFinite(r)?(r/1000).toFixed(3):'OL';unit=Number.isFinite(r)?'kΩ':'open path';message=`The battery is fully disconnected. ${Number.isFinite(r)?`The modeled path between ${s.red} and ${s.black} is ${r} Ω.`:'There is no conductive path between these nodes.'} Real in-circuit parallel paths can change readings.`}
 else{reading=r<30?'BEEP':'NO BEEP';unit=r<30?'continuous path':'threshold: 30 Ω';message=r<30?'This path is below the model’s 30 Ω continuity threshold. A beep shows a conductive path, not that a whole circuit is healthy.':Number.isFinite(r)?`There is ${r} Ω in this path, above the 30 Ω beep threshold. No beep does not always mean a broken connection.`:'The open resistor breaks this path, so there is no beep.'}
 $('#meter-screen').innerHTML=`${reading}<small>${unit||'CHECK SETUP'}</small>`;$('#meter-screen').style.fontSize=reading.length>6?'25px':'34px';$('#meter-feedback').textContent=message;$('#jack-label').textContent=(s.jack==='current'?'mA':'V / Ω')+' · RED';$('#fault-caption').textContent=s.fault==='healthy'?'Healthy circuit':s.fault==='open'?'Fault active: R1 is open (wire break)':'Fault active: R2 is bypassed (short)';
 const ys={A:60,B:174,C:280};$('#fault-art').innerHTML=(s.fault==='open'?'<rect x="348" y="86" width="34" height="50" fill="#183e36"/><path d="M365 86v8m0 28v14" stroke="#ed975c" stroke-width="3"/><text x="277" y="113">OPEN</text>':s.fault==='short'?'<path d="M365 174h-65v106h65" stroke="#ed975c" fill="none" stroke-width="3"/><text x="222" y="239">SHORT</text>':'')+(s.series?'<circle cx="210" cy="60" r="19" fill="#183e36" stroke="#d6ed99" stroke-width="2"/><text x="205" y="65">A</text><text x="166" y="30">Meter in series</text>':'');$('#probe-marks').innerHTML=s.series?'':['red','black'].map((p,i)=>`<path d="M${i?230:490} ${ys[s[p]]+35}L${i?348:380} ${ys[s[p]]}" stroke="${i?'#d7dfcc':'#ef9b83'}" stroke-width="4"/><text x="${i?216:480}" y="${ys[s[p]]+54}" fill="${i?'#d7dfcc':'#ef9b83'}">${p==='red'?'+ RED':'− COM'}</text>`).join('');document.querySelectorAll('[data-probe]').forEach(b=>{b.classList.toggle('active',b.dataset.probe===s.probe);b.setAttribute('aria-pressed',b.dataset.probe===s.probe)});$('#probe-red').disabled=s.series;$('#probe-black').disabled=s.series;
}
